# Дополнительные схемы по русскому языку: своя схема для каждой темы курса.
# Файл подключается из draw_ru.py (exec), использует его Pic, morph, card, цвета и meta.
# Все примеры – общеизвестные учебные примеры; правила сформулированы как в школьных учебниках.

CYC = [("blue", BLUE), ("red", RED), ("green", GREEN), ("gold", GOLD), ("violet", VIOLET)]
PUN = set(",.:;!?–—«»()…")


def wrap(p, text, size, maxw, bold=False):
    out, cur = [], ""
    for w in text.split():
        t = (cur + " " + w).strip()
        if p.tw(t, size, bold) <= maxw:
            cur = t
        else:
            if cur:
                out.append(cur)
            cur = w
    if cur:
        out.append(cur)
    return out


def header(p, head, y=30):
    hw = min(p.tw(head, 44, True), p.w - 160)
    lines = wrap(p, head, 44, p.w - 160, True)
    h = 50 * len(lines) + 46
    p.box(40, y, 40 + max(p.tw(l, 44, True) for l in lines) + 80, y + h, SOFT["gold"], GOLD, 24, 3)
    for i, l in enumerate(lines):
        p.text(80, y + 70 + i * 50, l, 44, INK, True)
    return y + h + 40


def boxes(name, title, caption, head, items, cols=3, flow=False, note=None, sub=30):
    W = 1700
    p = Pic(W, 2600)
    y = header(p, head)
    gap = 70 if flow else 30
    bw = (W - 80 - gap * (cols - 1)) / cols
    rows = [items[i:i + cols] for i in range(0, len(items), cols)]
    for r, row in enumerate(rows):
        hs = []
        for t, d in row:
            tl = wrap(p, t, 36, bw - 40, True)
            dl = wrap(p, d, sub, bw - 40) if d else []
            hs.append(46 * len(tl) + (sub + 10) * len(dl) + 50)
        h = max(hs)
        for i, (t, d) in enumerate(row):
            k = r * cols + i
            s, c = CYC[k % len(CYC)]
            x = 40 + i * (bw + gap)
            p.box(x, y, x + bw, y + h, SOFT[s], c, 22, 3)
            tl = wrap(p, t, 36, bw - 40, True)
            yy = y + 52
            for l in tl:
                p.text(x + bw / 2, yy, l, 36, INK, True, anchor="ms"); yy += 46
            for l in (wrap(p, d, sub, bw - 40) if d else []):
                p.text(x + bw / 2, yy + 4, l, sub, GREY, anchor="ms"); yy += sub + 10
            if flow and k < len(items) - 1 and i < cols - 1:
                ax = x + bw + 10; ay = y + h / 2
                p.line([(ax, ay), (ax + gap - 20, ay)], INK, 5)
                p.line([(ax + gap - 20, ay), (ax + gap - 36, ay - 14)], INK, 5); p.line([(ax + gap - 20, ay), (ax + gap - 36, ay + 14)], INK, 5)
        y += h + 30
    if note:
        for l in wrap(p, note, 32, W - 120):
            y += 44; p.text(60, y, l, 32, GREY)
    p.save(name, title, caption)


def colored(p, x, y, s, size, color=INK, pcolor=RED):
    for ch in s:
        if ch in PUN:
            x = p.text(x, y, ch, size, pcolor, True)
        else:
            x = p.text(x, y, ch, size, color)
    return x


def punct(name, title, caption, head, ex, note=None):
    W = 1700
    p = Pic(W, 2400)
    y = header(p, head) + 30
    for sent, scheme in ex:
        for l in wrap(p, sent, 44, W - 140):
            colored(p, 70, y, l, 44); y += 60
        if scheme:
            p.text(110, y + 6, scheme, 40, BLUE, mono=True); y += 70
        y += 34
    if note:
        for l in wrap(p, note, 32, W - 120):
            p.text(70, y, l, 32, GREY); y += 44
    p.save(name, title, caption)


def members(name, title, caption, rows, note=None, legend=True):
    """rows: [(слова, виды подчёркивания)]; вид None – без линии."""
    W = 1800
    p = Pic(W, 1800)
    y = 130
    for ws, kinds in rows:
        sp = p.words(60, y, ws, 54)
        for (a, b), k, w in zip(sp, kinds, ws):
            if not k:
                continue
            b2 = b - sum(p.tw(ch, 54) for ch in w[len(w.rstrip(",.:;!?–")):])
            p.under(a, b2, y + 18, k, RED if k in ("single", "double") else BLUE)
        y += 140
    if legend:
        used = []
        for _, kinds in rows:
            for k in kinds:
                if k and k not in used:
                    used.append(k)
        names = {"single": "подлежащее", "double": "сказуемое", "dash": "дополнение", "wavy": "определение", "dashdot": "обстоятельство"}
        for i, k in enumerate([k for k in ["single", "double", "dash", "wavy", "dashdot"] if k in used]):
            xx, yy = 60 + (i % 3) * 560, y + 20 + (i // 3) * 100
            p.under(xx, xx + 120, yy, k, RED if k in ("single", "double") else BLUE); p.text(xx + 150, yy + 12, names[k], 36)
        y += 100 * ((len(used) + 2) // 3) + 30
    if note:
        for l in wrap(p, note, 32, W - 120):
            p.text(60, y + 30, l, 32, GREY); y += 44
    p.save(name, title, caption)


def morphs(name, title, caption, words_, note=None, size=76):
    """words_: [(части, виды)] – виды: pref/root/suf/end/none; основа скобкой снизу."""
    W = 1700
    p = Pic(W, 1600)
    x, y = 70, 190
    for parts, kinds in words_:
        width = sum(p.tw(t, size) for t in parts)
        if x + width > W - 60:
            x = 70; y += 200
        sp = p.word(x, y, parts, size)
        morph(p, sp, kinds, y - size * .8, y + 20)
        base = [s for s, k in zip(sp, kinds) if k != "end"]
        if base:
            a, b = base[0][0], base[-1][1]
            p.line([(a, y + 32), (a, y + 48), (b, y + 48), (b, y + 32)], RED, 4)
        x = sp[-1][1] + 110
    y += 120
    if note:
        for l in wrap(p, note, 34, W - 120):
            p.text(70, y, l, 34, GREY); y += 48
    p.save(name, title, caption)


def table(name, title, caption, head, cols, rows, widths=None, size=42):
    W = 1700
    p = Pic(W, 2400)
    y = header(p, head)
    n = len(cols)
    widths = widths or [(W - 80) / n] * n
    rh = size + 34
    x = 40
    for i, c in enumerate(cols):
        p.d.rectangle([x, y, x + widths[i], y + rh], fill=SOFT["blue"], outline=BLUE, width=3)
        p.text(x + 18, y + rh - 22, c, size, INK, True); x += widths[i]
    y += rh
    for r in rows:
        x = 40
        for i, c in enumerate(r):
            p.d.rectangle([x, y, x + widths[i], y + rh], fill="white", outline=BLUE, width=2)
            parts = c.split("*")
            xx = x + 18
            for k, t in enumerate(parts):
                xx = p.text(xx, y + rh - 22, t, size, RED if k % 2 else INK, bool(k % 2))
            x += widths[i]
        y += rh
    p.save(name, title, caption)


def soundsch(name, title, caption, items, note=None):
    """items: [(слово, транскрипция, [цвета звуков], ударный индекс)]"""
    W = 1700
    p = Pic(W, 1600)
    y = 60
    for word_, tr, cols, acc in items:
        p.text(60, y + 90, word_, 70)
        p.text(60, y + 160, tr, 44, GREY)
        for i, c in enumerate(cols):
            x = 760 + i * 120
            p.d.rectangle([x, y + 30, x + 100, y + 120], fill=c, outline=INK, width=3)
            if i == acc:
                p.line([(x + 40, y + 18), (x + 62, y - 6)], INK, 6)
        y += 230
    for i, (c, t) in enumerate([(RED, "гласный"), (BLUE, "твёрдый согласный"), (GREEN, "мягкий согласный")]):
        x = 60 + i * 520
        p.d.rectangle([x, y + 10, x + 60, y + 54], fill=c, outline=INK, width=2); p.text(x + 80, y + 48, t, 34)
    if note:
        p.text(60, y + 130, note, 32, GREY)
    p.save(name, title, caption)


